func:
const respuesta = msg.payload;

if (
    !respuesta ||
    !respuesta.main ||
    !respuesta.wind
) {
    const estadoApi =
        msg.statusCode || null;

    msg.statusCode = 502;

    msg.payload = {
        ok: false,
        mensaje: "No se pudo obtener información meteorológica",
        estado_api_clima: estadoApi,
        respuesta_api_clima: respuesta || null
    };

    return msg;
}

const precipitacion =
    respuesta.rain?.["1h"] || 0;

const codigoClima =
    respuesta.weather?.[0]?.id || null;

const descripcionClima =
    respuesta.weather?.[0]?.description || "";

const vientoKmH =
    Number(
        (respuesta.wind.speed * 3.6)
            .toFixed(2)
    );

msg.statusCode = 200;

msg.payload = {
    ok: true,

    latitud: respuesta.coord.lat,
    longitud: respuesta.coord.lon,

    temperatura: respuesta.main.temp,

    velocidad_viento: vientoKmH,

    precipitacion: precipitacion,

    codigo_clima: codigoClima,

    descripcion_clima: descripcionClima,

    fecha_hora_clima:
        new Date(
            respuesta.dt * 1000
        ).toISOString()
};

msg.headers = {
    "Content-Type":
        "application/json; charset=utf-8"
};

return msg;
